# area: paramspec_concatenate
# hypothesis: A decorator typed with Concatenate[int, P] removes the injected leading int from the wrapped signature, so calling with a misplaced argument is rejected by checkers, and at runtime the wrapper fills in the int so the valid call succeeds.
from collections.abc import Callable
from typing import Concatenate, ParamSpec, TypeVar, reveal_type

P = ParamSpec('P')
R = TypeVar('R')


def with_attempts(fn: Callable[Concatenate[int, P], R]) -> Callable[P, R]:
    def wrapper(*args: P.args, **kwargs: P.kwargs) -> R:
        return fn(3, *args, **kwargs)
    return wrapper


@with_attempts
def add(attempts: int, name: str, *, scale: int = 1) -> str:
    return name * attempts * scale


out = add('ab', scale=2)
reveal_type(out)
print(out)
try:
    bad = add(1, 'ab')  # expect-error
    print(bad)
except TypeError as exc:
    print('TypeError:', exc)
